contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 diffArg) public {
        c.AdjustDifficulty(diffArg); if (__ESBMC_reverted()) return;
        uint256 before = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        uint256 afterVal = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        assert(afterVal == diffArg && before == diffArg);
    }
}

