pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 diffArg) internal {
        try c.AdjustDifficulty(diffArg) {} catch { return; }
        uint256 before;
        try c.currentDifficulty() returns (uint256 __r) { before = __r; } catch { return; }
        uint256 afterVal;
        try c.currentDifficulty() returns (uint256 __r) { afterVal = __r; } catch { return; }
        assertTrue(afterVal == diffArg && before == diffArg);
    }

    function testFuzz_run(uint256 diffArg) public {
        _run(diffArg);
    }

    receive() external payable {}
}
